@Test
void testCompletionEvent() {
    JdbcSourceConfig config = mock(JdbcSourceConfig.class);
    AbstractSchemaChangeResolver resolver = new AbstractSchemaChangeResolver(config) {

        @Override
        protected DdlParser createDdlParser(TablePath tablePath) {
            return null;
        }

        @Override
        protected List<AlterTableColumnEvent> getAndClearParsedEvents() {
            return Collections.emptyList();
        }

        @Override
        protected String getSourceDialectName() {
            return "mysql";
        }
    };
    AlterTableChangeColumnEvent changeColumnEvent = AlterTableChangeColumnEvent.change(TableIdentifier.of(null, "test_db", "test_table"), "old_column", PhysicalColumn.builder().name("new_column").build());
    CatalogTable catalogTable = CatalogTable.of(TableIdentifier.of(null, "test_db", "test_table"), TableSchema.builder().column(PhysicalColumn.builder().name("old_column").dataType(BasicType.STRING_TYPE).columnLength(1L).comment("column comment").build()).build(), Collections.emptyMap(), Collections.emptyList(), null, null);
    List<AlterTableColumnEvent> events = resolver.completionEvent(Arrays.asList(changeColumnEvent), Arrays.asList(catalogTable));
    changeColumnEvent = (AlterTableChangeColumnEvent) events.get(0);
    Assertions.assertEquals("mysql", changeColumnEvent.getSourceDialectName());
    Assertions.assertEquals(BasicType.STRING_TYPE, changeColumnEvent.getColumn().getDataType());
    Assertions.assertEquals(1L, changeColumnEvent.getColumn().getColumnLength());
    Assertions.assertEquals("column comment", changeColumnEvent.getColumn().getComment());
}

